# Reconstruct the test grid, then apply the sequence path by painting only the 8-valued cells between consecutive 2x2 objects.
H=W=30
g=[[1]*W for _ in range(H)]
# 3x3 panels' 6x6 interiors
row_starts=[1,9,16]  # zero-based starts of 6-row 8 interiors
col_starts=[1,10,20] # zero-based starts of 6-column 8 interiors
for rs in row_starts:
    for cs in col_starts:
        for r in range(rs,rs+6):
            for c in range(cs,cs+6): g[r][c]=8
# objects (label, row index, col index), each is 2x2
labels=[[2,4,3],[3,6,9],[9,4,5]]
rows=[3,11,18]
cols=[3,12,22]
objs={}
for i in range(3):
    for j in range(3):
        label=labels[i][j]; r=rows[i]; c=cols[j]
        for rr in range(r,r+2):
            for cc in range(c,c+2): g[rr][cc]=label
        objs[(i,j)]=(label,r,c)
# encoded route maps to unique adjacent objects as determined from the labels
route=[(0,0),(0,1),(0,2),(1,2),(2,2),(2,1),(1,1),(1,0),(2,0)]
for (i,j),(ni,nj) in zip(route,route[1:]):
    label,r,c=objs[(i,j)]; _,rr,cc=objs[(ni,nj)]
    if r==rr:
        lo,hi=sorted((c+1,cc+1))
        # these two rows, only fill intervening background cells
        for y in (r,r+1):
            for x in range(lo,hi):
                if g[y][x]==8: g[y][x]=label
    elif c==cc:
        lo,hi=sorted((r+1,rr+1))
        for x in (c,c+1):
            for y in range(lo,hi):
                if g[y][x]==8: g[y][x]=label
    else: raise ValueError('route not aligned')
# key at zero-based row 28
seq=[2,4,3,9,5,4,6,3,9]
for k,v in enumerate(seq): g[28][1+2*k]=v
print('\n'.join(' '.join(map(str,row)) for row in g))

# Candidate 2: extend each object only through the 8-background on its side, stopping at the first 1-divider.
g2=[[1]*30 for _ in range(30)]
for rs in [1,9,16]:
    for cs in [1,10,20]:
        for r in range(rs,rs+6):
            for c in range(cs,cs+6): g2[r][c]=8
objs={}
for i in range(3):
    for j in range(3):
        label=labels[i][j]; r=rows[i]; c=cols[j]
        for rr in range(r,r+2):
            for cc in range(c,c+2): g2[rr][cc]=label
        objs[(i,j)]=(label,r,c)
for (i,j),(ni,nj) in zip(route,route[1:]):
    label,r,c=objs[(i,j)]; _,rr,cc=objs[(ni,nj)]
    if r==rr:
        dc=1 if cc>c else -1
        for y in (r,r+1):
            x=(c+2 if dc>0 else c-1)
            while 0<=x<30 and g2[y][x]==8:
                g2[y][x]=label; x+=dc
    else:
        dr=1 if rr>r else -1
        for x in (c,c+1):
            y=(r+2 if dr>0 else r-1)
            while 0<=y<30 and g2[y][x]==8:
                g2[y][x]=label; y+=dr
for k,v in enumerate(seq): g2[28][1+2*k]=v
print(json.dumps(g2,separators=(',',':')))

# Candidate 3: lines use the true outside/background color (1), not the panel fill (8).
g3=[[1]*30 for _ in range(30)]
for rs in [1,9,16]:
    for cs in [1,10,20]:
        for r in range(rs,rs+6):
            for c in range(cs,cs+6): g3[r][c]=8
objs={}
for i in range(3):
    for j in range(3):
        label=labels[i][j]; r=rows[i]; c=cols[j]
        for rr in range(r,r+2):
            for cc in range(c,c+2): g3[rr][cc]=label
        objs[(i,j)]=(label,r,c)
for (i,j),(ni,nj) in zip(route,route[1:]):
    label,r,c=objs[(i,j)]; _,rr,cc=objs[(ni,nj)]
    if r==rr:
        for y in (r,r+1):
            for x in range(min(c,cc)+2, max(c,cc)):
                if g3[y][x]==1: g3[y][x]=label
    else:
        for x in (c,c+1):
            for y in range(min(r,rr)+2,max(r,rr)):
                if g3[y][x]==1: g3[y][x]=label
for k,v in enumerate(seq): g3[28][1+2*k]=v
print(json.dumps(g3,separators=(',',':')))
